import re

def parse(lines):
    skip = []
    fields = []; fl = []
    sizes = []; sl = []
    decls = []; dl = []
    irf = []; il = []
    lay = []; ll = []
    bf = []; bl = []
    rec = None; mode = None; cur = None; curlay = None
    for i, l in enumerate(lines):
        if not l.strip():
            continue
        if l.startswith('*** Dumping'):
            mode = 'ir' if 'IRgen' in l else 'ast'
            rec = None; cur = None; curlay = None
            skip.append(i)
            continue
        if mode == 'ast':
            m = re.match(r'^\s*(\S*) \| (.*)$', l)
            if not m:
                continue
            off, rest = m.group(1), m.group(2)
            body = rest.lstrip()
            if body.startswith('['):
                kv = dict(re.findall(r'(\w+)=([^,\]]+)', body))
                sizes.append({'record': rec or '', 'sizeof': kv.get('sizeof', ''), 'align': kv.get('align', '')})
                sl.append(i)
                continue
            depth = (len(rest) - len(body)) // 2
            if depth == 0:
                rec = body.strip()
                fl.append(i)
                continue
            if body.endswith(' ') or ' ' not in body.strip():
                typ, name = body.strip(), ''
            else:
                typ, name = body.rsplit(' ', 1)
            fields.append({'record': rec or '', 'Offset': off, 'Depth': depth, 'Type': typ.strip(), 'Name': name})
            fl.append(i)
            continue
        if mode == 'ir':
            m = re.match(r'^Record: (?P<kind>\w+) (?P<addr>0x[0-9a-fA-F]+) <(?P<range>[^>]*)> (?P<loc>\S+) (?P<rec>.*?)(?: definition)?$', l)
            if m:
                rec = m.group('rec')
                decls.append({'record': rec, 'Kind': m.group('kind'), 'Address': m.group('addr'), 'Range': m.group('range'), 'Location': m.group('loc')})
                dl.append(i)
                continue
            m = re.match(r"^[|`]-FieldDecl (?P<addr>0x[0-9a-fA-F]+) <(?P<range>[^>]*)> (?P<loc>\S+) (?:(?P<name>\w+) )?'(?P<type>[^']*)'", l)
            if m:
                cur = {'record': rec or '', 'Address': m.group('addr'), 'Range': m.group('range'), 'Location': m.group('loc'), 'Name': m.group('name') or '', 'Type': m.group('type'), 'BitWidth': ''}
                irf.append(cur)
                il.append(i)
                continue
            if re.match(r'^[|` ]\s+[|`]-', l):
                v = re.search(r'value: Int (\d+)', l)
                if v and cur is not None:
                    cur['BitWidth'] = v.group(1)
                il.append(i)
                continue
            m = re.match(r'^\s*LLVMType:(.*)$', l)
            if m:
                curlay = {'record': rec or '', 'LLVMType': m.group(1).strip(), 'IsZeroInitializable': ''}
                lay.append(curlay)
                ll.append(i)
                continue
            m = re.match(r'^\s*IsZeroInitializable:(\S+)', l)
            if m:
                if curlay is None:
                    curlay = {'record': rec or '', 'LLVMType': '', 'IsZeroInitializable': ''}
                    lay.append(curlay)
                curlay['IsZeroInitializable'] = m.group(1)
                ll.append(i)
                continue
            if '<CGBitFieldInfo' in l:
                row = {'record': rec or ''}
                for k, v in re.findall(r'(\w+):([^\s>]+)', l):
                    row[k] = v
                bf.append(row)
                bl.append(i)
                continue
            if re.match(r'^\s*(Layout: <CGRecordLayout|BitFields:\[|\]>)', l):
                skip.append(i)
                continue
    blocks = []
    for name, recs, idx in (('ast_fields', fields, fl), ('record_sizes', sizes, sl), ('record_decls', decls, dl), ('field_decls', irf, il), ('irgen_layouts', lay, ll), ('bitfields', bf, bl)):
        if idx:
            blocks.append({'name': name, 'kind': 'table', 'lines': idx, 'records': recs})
    return {'blocks': blocks, 'skip': skip}
